proof_hits=[]
for path in sorted((ROOT/'metadata').glob('*emulation*.json')):
 if path==report_path:continue
 data=json.loads(path.read_text(encoding='utf-8-sig'));matches=[]
 def walk(v,field=''):
  if isinstance(v,dict):
   for k,x in v.items():
    if k.replace('\\','/') in sources+['src/unit_01605.c']:matches.append({'source':k,'field':field+'/'+k,'value':x})
    walk(x,field+'/'+k)
  elif isinstance(v,list):
   for j,x in enumerate(v):walk(x,field+'/'+str(j))
 walk(data)
 if matches:proof_hits.append({'report':rel(path),'matches':matches})
assert not proof_hits,proof_hits
